import { getStudioProApi } from "@mendix/extensions-api";
import { Logger, ILogObj } from "tslog";

type StudioProApi = Awaited<ReturnType<typeof getStudioProApi>>;

// Generate daily log filename
function getDailyLogFileName(): string {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `agenteditor/log/log-${year}-${month}-${day}.log`;
}

// Custom transport for Studio Pro Files API
class StudioProFileTransport {
    private filePath: string;
    private studioPro: StudioProApi;
    private logQueue: string[] = [];
    private isProcessing = false;

    constructor(filePath: string, studioPro: StudioProApi) {
        this.filePath = filePath;
        this.studioPro = studioPro;
    }

    public log(logObj: ILogObj): void {
        // Format log entry as plain text
        const meta = logObj._meta as { date: Date; logLevelName: string };
        const timestamp = new Date(meta.date).toISOString();
        const level = meta.logLevelName.toUpperCase();

        // Extract all arguments from the log object
        const args: unknown[] = [];
        for (const key in logObj) {
            if (key !== "_meta") {
                args.push(logObj[key]);
            }
        }

        // Custom JSON stringifier that includes undefined values and error stacks
        const message = args
            .map((arg: unknown) => {
                if (arg instanceof Error) {
                    // Format Error objects with stack trace
                    return JSON.stringify({
                        name: arg.name,
                        message: arg.message,
                        stack: arg.stack,
                    });
                } else if (typeof arg === "object" && arg !== null) {
                    return JSON.stringify(arg, (key, value) => (value === undefined ? null : value));
                }
                return String(arg);
            })
            .join(" ");

        const logEntry = `[${timestamp}] ${level}: ${message}\n`;

        // Add to queue
        this.logQueue.push(logEntry);

        // Process queue (non-blocking)
        this.processQueue();
    }

    private async processQueue(): Promise<void> {
        // Prevent concurrent processing
        if (this.isProcessing || this.logQueue.length === 0) return;

        this.isProcessing = true;

        try {
            // Process all queued logs
            const logsToWrite = [...this.logQueue];
            this.logQueue = [];

            // Read existing content
            let existingContent = "";
            try {
                existingContent = (await this.studioPro.app.files.getFile(this.filePath)) || "";
            } catch {
                // File doesn't exist yet
            }

            // Append and write
            await this.studioPro.app.files.putFile(this.filePath, existingContent + logsToWrite.join(""));
        } catch (error) {
            console.error("Failed to write logs to file:", error);
            // Don't re-add to queue to avoid infinite loops
        } finally {
            this.isProcessing = false;

            // Process any logs that arrived during write
            if (this.logQueue.length > 0) {
                setTimeout(() => this.processQueue(), 0);
            }
        }
    }
}

// Create logger with extensibility files API as custom transport
export function createStudioProLogger(studioPro: StudioProApi): Logger<ILogObj> {
    const finalLogPath = getDailyLogFileName();
    const transport = new StudioProFileTransport(finalLogPath, studioPro);

    const logger = new Logger<ILogObj>({
        minLevel: 0, // 0: silly, 1: trace, 2: debug, 3: info, 4: warn, 5: error, 6: fatal
        type: "pretty",
        stylePrettyLogs: false, // No colors in console
        hideLogPositionForProduction: true, // Hides file path and line number
    });

    // Attach custom transport
    logger.attachTransport((logObj) => {
        transport.log(logObj);
    });

    return logger;
}
